    "inlineSchema": "// ────────────────────────────────────────────────\n// Company (belongs to employer)\nmodel Company {\n  id                 String             @id @default(uuid())\n  name               String\n  slug               String             @unique\n  description        String?\n  website            String?\n  logoUrl            String?\n  address            String?\n  verificationStatus VerificationStatus @default(PENDING)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  employerProfiles EmployerProfile[]\n  jobs             Job[]\n\n  @@map(\"companies\")\n}\n\nenum UserRole {\n  JOB_SEEKER\n  EMPLOYER\n  MODERATOR\n  ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  DELETED\n}\n\nenum VerificationStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\nenum JobStatus {\n  DRAFT\n  PENDING_REVIEW\n  PUBLISHED\n  PAUSED\n  CLOSED\n  FLAGGED\n}\n\nenum ApplicationStatus {\n  SUBMITTED\n  VIEWED\n  SHORTLISTED\n  INTERVIEW\n  OFFERED\n  HIRED\n  REJECTED\n  WITHDRAWN\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum JobType {\n  FULL_TIME\n  PART_TIME\n  CONTRACT\n  INTERNSHIP\n  FREELANCE\n  REMOTE\n  GOVT\n  NGO\n  PRIVATE\n  HYBRID\n}\n\nmodel Job {\n  id        String  @id @default(uuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id])\n\n  title               String\n  slug                String\n  description         String\n  employmentType      String // or enum\n  workplaceType       String // or enum\n  experienceMin       Int?\n  experienceMax       Int?\n  salaryMin           Float?\n  salaryMax           Float?\n  currency            String    @default(\"BDT\")\n  vacancies           Int       @default(1)\n  applicationDeadline DateTime?\n\n  status JobStatus @default(DRAFT)\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  publishedAt DateTime?\n\n  //applications Application[]\n  //bookmarks    Bookmark[]\n\n  // skills, locations, etc.\n\n  @@map(\"jobs\")\n}\n\n// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../../src/prisma/generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ────────────────────────────────────────────────\n// Core shared user (authentication + role)\nmodel User {\n  id                 String     @id @default(uuid())\n  email              String     @unique\n  phone              String?\n  passwordHash       String\n  needPasswordChange Boolean    @default(true)\n  role               UserRole\n  status             UserStatus @default(ACTIVE)\n\n  // Very minimal shared profile fields (optional)\n  fullName        String?\n  profilePhotoUrl String?\n\n  lastLoginAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  // Relations — only one of these should be non-null depending on role\n  jobSeekerProfile JobSeekerProfile?\n  employerProfile  EmployerProfile?\n  moderatorProfile ModeratorProfile?\n  adminProfile     AdminProfile?\n\n  // ── relations ─────────────────────────────────────\n  //applications Application[]\n  //bookmarks    Bookmark[]\n  //alerts       Alert[]\n  //auditLogs    AuditLog[]\n\n  // Optional: refresh tokens, reports made, etc.\n  @@map(\"users\")\n}\n\n// ────────────────────────────────────────────────\n// Job Seeker specific profile\nmodel JobSeekerProfile {\n  id String @id @default(uuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  fullName          String?\n  dateOfBirth       DateTime?\n  gender            Gender?\n  currentLocationId String?\n  expectedSalaryMin Int?\n  expectedSalaryMax Int?\n  experienceYears   Int?\n  about             String?\n\n  // Preferences\n  preferredJobTypes  JobType[]\n  preferredLocations String[]\n\n  profileCompletion Int?     @default(0)\n  isProfileVerified Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  // ── relations ─────────────────────────────────────\n  //resumes      Resume[]\n  //seekerSkills SeekerSkill[]\n  //applications Application[] @relation(\"Applicant\")\n  //bookmarks    Bookmark[]\n  //alerts       Alert[]\n\n  @@map(\"job_seeker_profiles\")\n}\n\n// ────────────────────────────────────────────────\n// Employer specific profile\nmodel EmployerProfile {\n  id String @id @default(uuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Restrict)\n\n  designation String?\n  contactName String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"employer_profiles\")\n}\n\n// ────────────────────────────────────────────────\n// Moderator lightweight profile\nmodel ModeratorProfile {\n  id String @id @default(uuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Optional moderator-specific settings\n  bio             String?\n  assignedRegions String[] // e.g. divisions they moderate\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"moderator_profiles\")\n}\n\n// ────────────────────────────────────────────────\n// Admin lightweight profile\nmodel AdminProfile {\n  id String @id @default(uuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Optional admin-specific fields\n  permissions Json? // future-proofing\n  department  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"admin_profiles\")\n}\n\n// ... rest of your schema (Job, Application, Resume, Skill, Location, Bookmark, Alert, AuditLog, etc.)\n",
